public class MyTokenProvider : ITokenDataProvider
{
    public bool SupportsCreation => true;

    public Task<IEnumerable<IToken>> SearchTokensAsync(string query, CancellationToken ct = default)
    {
        var tokens = new List<MyToken>
        {
            new() { Key = "user.email",    DisplayName = "User Email",    Icon = "📧", TypeLabel = "Email",  ColorClass = "token-url" },
            new() { Key = "api.secret",    DisplayName = "API Secret",    Icon = "🔒", TypeLabel = "Secret", ColorClass = "token-secret" },
            new() { Key = "order.total",   DisplayName = "Order Total",   Icon = "💰", TypeLabel = "Number", ColorClass = "token-number" },
        };
        return Task.FromResult(
            tokens.Where(t => t.Key.Contains(query, StringComparison.OrdinalIgnoreCase)
                            || t.DisplayName.Contains(query, StringComparison.OrdinalIgnoreCase))
                  .Cast<IToken>());
    }

    public void Refresh() { }
}

public class MyToken : IToken
{
    public string Key { get; set; } = string.Empty;
    public string DisplayName { get; set; } = string.Empty;
    public string? Description { get; set; }
    public string? Category { get; set; }
    public string? Icon { get; set; }
    public string? ColorClass { get; set; }
    public string? TypeLabel { get; set; }
}
